import{_ as a,C as i,o,c as n,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse(`{"title":"A Positive Judgment Is Not Yet an Effective Approval","description":"","frontmatter":{"title":"A Positive Judgment Is Not Yet an Effective Approval","date":"2026-09-05","column":"digital-employee","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"在人工智能生成的批准判断成为组织内有效签署之前，必须具备哪些证据；哪些变化应当使这份权限失效或收窄？","summary":"GitHub's code-review controls and OpenAI Codex's authorization-evidence lifecycle expose the same boundary: judgment, approval capability, gate effect, scope, and freshness are different facts. A material change to the target, policy, or authorization evidence requires re-evaluation.","sources":["research/analysis/Q-20260905-01-approval-authority-freshness.md"],"item_id":"Q-20260905-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-05-judgment-is-not-effective-approval-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-09-05-judgment-is-not-effective-approval.md","filePath":"en/digital-employee/2026-09-05-judgment-is-not-effective-approval.md","lastUpdated":1788754225000}`),l={name:"en/digital-employee/2026-09-05-judgment-is-not-effective-approval.md"};function d(c,e,p,h,u,m){const t=i("ArticleCover");return o(),n("div",null,[r(t,{image:"/assets/covers/daily-2026-09-05-judgment-is-not-effective-approval-editorial-v2.webp",kicker:"Digital Employee · Daily Research",title:"A Positive Judgment Is Not Yet an Effective Approval",summary:"GitHub's code-review controls and OpenAI Codex's authorization-evidence lifecycle expose the same boundary: judgment, approval capability, gate effect, scope, and freshness are different facts. A material change to the target, policy, or authorization evidence requires re-evaluation.",version:"Q-20260905-01",status:"Daily Runtime V5 · 2026-09-05",languageHref:"/zh/digital-employee/2026-09-05-judgment-is-not-effective-approval",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-positive-judgment-is-not-yet-an-effective-approval" tabindex="-1">A Positive Judgment Is Not Yet an Effective Approval <a class="header-anchor" href="#a-positive-judgment-is-not-yet-an-effective-approval" aria-label="Permalink to &quot;A Positive Judgment Is Not Yet an Effective Approval&quot;">​</a></h1><p>An AI review says a change is acceptable. Minutes later, the target commit, covered files, or authorization policy changes, but the system continues to treat the old judgment as an effective approval. The dangerous mistake is not necessarily in the review. It is in turning “the model thinks this is acceptable” into “this decision is authorized to satisfy the gate now.”</p><p>The core proposition is: <strong>an AI approval judgment becomes an effective sign-off only when separately authorized for a named gate, scope, and freshness identity. A material change to the reviewed object, governing evidence, or authority-sensitive context must invalidate or re-evaluate that authority.</strong> This gives system designers a practical replacement for one overloaded approved flag.</p><h2 id="one-word-hides-five-governance-questions" tabindex="-1">One Word Hides Five Governance Questions <a class="header-anchor" href="#one-word-hides-five-governance-questions" aria-label="Permalink to &quot;One Word Hides Five Governance Questions&quot;">​</a></h2><p>“Approval” may refer to at least five different facts:</p><ol><li><strong>Judgment:</strong> did the model assess the object as acceptable?</li><li><strong>Approval capability:</strong> does current policy allow this actor or agent to submit an approval?</li><li><strong>Effective authority:</strong> may that approval satisfy the particular organizational or runtime gate?</li><li><strong>Scope:</strong> which repository, files, action, principal relationship, or parameter set does it cover?</li><li><strong>Freshness identity:</strong> which target version, policy version, and authorization-evidence version were evaluated?</li></ol><p>These dimensions can all be true at once, but they can also change independently. A reasonable judgment does not create approval capability. The ability to submit an approval does not necessarily make it qualify for a merge gate. Authority that was valid for yesterday&#39;s commit does not automatically cover today&#39;s one.</p><p>A three-second example makes the difference concrete. The unsafe design stores only <code>approved=true</code>. The governed design stores: positive judgment; policy permits submission; the approval satisfies a named merge gate; the scope is a specified path set; and both target and authorization-evidence versions remain current. A change to any protected identity then produces an explicit re-evaluation instead of relying on the same green label.</p><h2 id="the-organizational-sample-separates-assessment-submission-and-gate-effect" tabindex="-1">The Organizational Sample Separates Assessment, Submission, and Gate Effect <a class="header-anchor" href="#the-organizational-sample-separates-assessment-submission-and-gate-effect" aria-label="Permalink to &quot;The Organizational Sample Separates Assessment, Submission, and Gate Effect&quot;">​</a></h2><p>GitHub&#39;s public Copilot code-review materials distinguish several layers. Copilot code review can provide an approval assessment without that assessment counting toward pull-request merge requirements. The ability to submit approving reviews is disabled by default and requires administrator enablement. Whether such approval may satisfy merge requirements is configured separately. Repository policy can further limit qualifying approval by changed-file paths.</p><p>GitHub also documents that new commits dismiss an earlier approval. That rule makes reviewed-object freshness explicit. Approval does not attach indefinitely to the natural-language idea that “this pull request looks fine”; its effect depends on the version that was reviewed. When the target changes, the merge-governance system requires a fresh effective decision.</p><p>These are public primary-source product facts from GitHub&#39;s own announcement and documentation, not independent third-party validation. They establish what the exposed controls separate. They do not reveal every internal authorization mechanism or prove a human principal&#39;s legal identity.</p><h2 id="the-agent-runtime-sample-makes-context-an-authority-boundary" tabindex="-1">The Agent-Runtime Sample Makes Context an Authority Boundary <a class="header-anchor" href="#the-agent-runtime-sample-makes-context-an-authority-boundary" aria-label="Permalink to &quot;The Agent-Runtime Sample Makes Context an Authority Boundary&quot;">​</a></h2><p>An OpenAI Codex maintainer change versions root-authorization evidence used by its Guardian review path. If a pending <code>Allow</code> has not yet been consumed and the root-authorization version changes, the stale allow is cancelled. Required evidence that is absent leaves the review incomplete. The covered implementation also handles two context transitions: it restores required root authorization across compaction and strips parent-only approvals when a worker is forked.</p><p>This is not the same protocol or gate as GitHub pull-request policy. Codex is deciding whether a running agent may proceed under current root instructions and verified answers. The comparable higher-order invariant is narrower: a positive result must refer to authorization evidence that is still valid. Preserved text or conversational continuity cannot by itself imply preserved privilege.</p><p>The evidence is a merged maintainer implementation plus targeted tests for the covered paths. It supports claims about that revision. It is not independent safety validation of all agents, tools, or organizational governance.</p><h2 id="invalidation-should-follow-enumerated-change-not-intuition" tabindex="-1">Invalidation Should Follow Enumerated Change, Not Intuition <a class="header-anchor" href="#invalidation-should-follow-enumerated-change-not-intuition" aria-label="Permalink to &quot;Invalidation Should Follow Enumerated Change, Not Intuition&quot;">​</a></h2><p>A usable authority lifecycle can be expressed as responsibilities rather than one state label:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Owner</th><th>Input</th><th>Output</th><th>Stop condition</th></tr></thead><tbody><tr><td>Form judgment</td><td>Review model</td><td>Target version and evidence</td><td>Reasoned positive or negative assessment</td><td>Target or evidence is insufficient</td></tr><tr><td>Grant approval capability</td><td>Policy control plane</td><td>Principal, policy, capability settings</td><td>Permission to submit approval</td><td>Policy disabled or actor ineligible</td></tr><tr><td>Create gate effect</td><td>Organizational gate</td><td>Approval, scope, gate rules</td><td>Named gate satisfied</td><td>Scope mismatch or approval does not qualify</td></tr><tr><td>Check freshness</td><td>Version and authorization verifier</td><td>Target, policy, evidence, context identities</td><td>Preserve or revoke effect</td><td>A protected identity changes materially</td></tr><tr><td>Perform downstream action</td><td>Merger or runtime executor</td><td>Current effective gate result</td><td>Bounded effect</td><td>Authority expired, consumed, or effect state unknown</td></tr></tbody></table><p>“Material change” cannot remain an intuition. Candidate triggers include a reviewed commit change, a change to the qualified path set, a policy update, a new authorization-evidence version, a principal-relationship change, or transfer of context ownership from parent to child. A system may preserve approval across a harmless change if it can define and audit a narrower rule showing that the approved proposition is unaffected.</p><h2 id="simple-interfaces-need-not-erase-durable-facts" tabindex="-1">Simple Interfaces Need Not Erase Durable Facts <a class="header-anchor" href="#simple-interfaces-need-not-erase-durable-facts" aria-label="Permalink to &quot;Simple Interfaces Need Not Erase Durable Facts&quot;">​</a></h2><p>Two counterarguments deserve attention. Re-reviewing every change can be expensive. Product interfaces may also combine states intentionally so users are not forced to read a control-plane model.</p><p>Both points are compatible with the proposition. A system can preserve approval for comment-only changes, files outside the approved scope, or other mutations mechanically shown not to affect the reviewed proposition. The predicate must be explicit. A user interface can show one “approved” label while the durable record retains who had capability, which gate was satisfied, what scope applied, and whether target and authorization versions still match.</p><p>The hazard is not visual simplification. It is reducing durable state to a Boolean. When challenged, such a system cannot answer whether the record was a recommendation, a policy authorization, or effective gate satisfaction; which object it covered; which authority version it used; or why it remains valid.</p><h2 id="evidence-boundary-and-open-questions" tabindex="-1">Evidence Boundary and Open Questions <a class="header-anchor" href="#evidence-boundary-and-open-questions" aria-label="Permalink to &quot;Evidence Boundary and Open Questions&quot;">​</a></h2><p>The two samples support separation of judgment from effective authority and the need for an explicit freshness identity. They do not establish a universal cross-platform approval protocol, human-principal identity, non-repudiation, legal accountability, or exactly-once downstream effects.</p><p>Open questions include which fields belong in a portable approval-authority identity; which target or policy changes may safely preserve approval; how in-flight work should be cancelled, reconciled, or compensated when authority becomes stale; whether an approval is single-use; how expiration, network replay, and renewed approval are distinguished; and which process, container, or operating-system controls must backstop an application-level gate.</p><p>An engineering team can begin with a small rule: prohibit an unexplained single approved flag in the next design review. Require separate answers for judgment, capability, gate effect, scope, and freshness—and enumerate what invalidates each answer. That is how a positive judgment stops surviving as authority after the facts that justified it have changed.</p><p><strong>Evidence and sources:</strong></p><ul><li><a href="https://github.blog/changelog/2026-09-01-copilot-code-review-can-now-approve-pull-requests/" target="_blank" rel="noreferrer">GitHub: Copilot code review can now approve pull requests (product announcement, September 1, 2026)</a></li><li><a href="https://docs.github.com/en/copilot/customizing-copilot/configuring-copilot-code-review/configuring-copilot-code-review" target="_blank" rel="noreferrer">GitHub Docs: Configuring Copilot code review</a></li><li><a href="https://github.com/openai/codex/commit/87628df77ab1a2622d1193ad835df02ced565bf2" target="_blank" rel="noreferrer">OpenAI Codex maintainer commit: version Guardian root-authorization evidence</a></li></ul>',30))])}const g=a(l,[["render",d]]);export{f as __pageData,g as default};
